import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cooperative_groups.h>
#include <algorithm>
namespace cg = cooperative_groups;
__device__ __forceinline__ void grid_barrier(unsigned int* __restrict__ counter,
                                             unsigned int* __restrict__ generation,
                                             const unsigned int num_blocks)
{
    (void)counter;
    (void)generation;
    (void)num_blocks;
    cg::this_grid().sync();
}

#define BN_THREADS 256

__global__ void bn2d_fused_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int64_t* __restrict__ num_batches_tracked,
    float* __restrict__ g_sum,
    float* __restrict__ g_sumsq,
    float* __restrict__ g_norm_mean,
    float* __restrict__ g_norm_inv,
    unsigned int* __restrict__ bar_counter,
    unsigned int* __restrict__ bar_gen,
    const int N,
    const int C,
    const long long S,
    const double momentum,
    const double eps,
    const bool training)
{
    const int tid = threadIdx.x;
    const long long global_tid = (long long)blockIdx.x * blockDim.x + tid;
    const long long nthreads = (long long)gridDim.x * blockDim.x;
    const long long total_slices = (long long)N * (long long)C;

    for (long long i = global_tid; i < (long long)C; i += nthreads) {
        g_sum[i] = 0.0f;
        g_sumsq[i] = 0.0f;
        g_norm_mean[i] = 0.0f;
        g_norm_inv[i] = 0.0f;
    }
    grid_barrier(bar_counter, bar_gen, (unsigned int)gridDim.x);

    __shared__ float red_sum[BN_THREADS];
    __shared__ float red_sumsq[BN_THREADS];

    for (long long slice = blockIdx.x; slice < total_slices; slice += gridDim.x) {
        const int c = (int)(slice % (long long)C);
        const long long base = slice * S;

        float partial_sum = 0.0f;
        float partial_sumsq = 0.0f;
        if ((S & 3LL) == 0LL) {
            const long long S4 = S >> 2;
            const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x + base);
            float sum0 = 0.0f, sum1 = 0.0f, sum2 = 0.0f, sum3 = 0.0f;
            float sq0 = 0.0f, sq1 = 0.0f, sq2 = 0.0f, sq3 = 0.0f;
            const long long stride = (long long)blockDim.x;
            const long long unroll = stride << 2;
            long long s4 = tid;
            for (; s4 + 3 * stride < S4; s4 += unroll) {
                const float4 v0 = x4[s4];
                const float4 v1 = x4[s4 + stride];
                const float4 v2 = x4[s4 + 2 * stride];
                const float4 v3 = x4[s4 + 3 * stride];
                sum0 += (v0.x + v0.y) + (v0.z + v0.w);
                sum1 += (v1.x + v1.y) + (v1.z + v1.w);
                sum2 += (v2.x + v2.y) + (v2.z + v2.w);
                sum3 += (v3.x + v3.y) + (v3.z + v3.w);
                sq0 += (v0.x * v0.x + v0.y * v0.y) + (v0.z * v0.z + v0.w * v0.w);
                sq1 += (v1.x * v1.x + v1.y * v1.y) + (v1.z * v1.z + v1.w * v1.w);
                sq2 += (v2.x * v2.x + v2.y * v2.y) + (v2.z * v2.z + v2.w * v2.w);
                sq3 += (v3.x * v3.x + v3.y * v3.y) + (v3.z * v3.z + v3.w * v3.w);
            }
            for (; s4 < S4; s4 += stride) {
                const float4 v = x4[s4];
                sum0 += (v.x + v.y) + (v.z + v.w);
                sq0 += (v.x * v.x + v.y * v.y) + (v.z * v.z + v.w * v.w);
            }
            partial_sum = ((sum0 + sum1) + (sum2 + sum3));
            partial_sumsq = ((sq0 + sq1) + (sq2 + sq3));
        } else {
            for (long long s = tid; s < S; s += blockDim.x) {
                const float v = x[base + s];
                partial_sum += v;
                partial_sumsq += v * v;
            }
        }

        // Warp-level reduction via shuffle intrinsics (single optimization),
        // then a final cross-warp reduction through shared memory by warp 0.
        // This removes the log2(blockDim) __syncthreads() tree-reduction steps.
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            partial_sum += __shfl_down_sync(0xffffffffu, partial_sum, offset);
            partial_sumsq += __shfl_down_sync(0xffffffffu, partial_sumsq, offset);
        }
        const int lane = tid & 31;
        const int warp = tid >> 5;
        const int num_warps = (int)(blockDim.x >> 5);
        if (lane == 0) {
            red_sum[warp] = partial_sum;
            red_sumsq[warp] = partial_sumsq;
        }
        __syncthreads();
        if (warp == 0) {
            float s = (lane < num_warps) ? red_sum[lane] : 0.0f;
            float sq = (lane < num_warps) ? red_sumsq[lane] : 0.0f;
            #pragma unroll
            for (int offset = 16; offset > 0; offset >>= 1) {
                s += __shfl_down_sync(0xffffffffu, s, offset);
                sq += __shfl_down_sync(0xffffffffu, sq, offset);
            }
            if (lane == 0) {
                atomicAdd(&g_sum[c], s);
                atomicAdd(&g_sumsq[c], sq);
            }
        }
        __syncthreads();
    }
    grid_barrier(bar_counter, bar_gen, (unsigned int)gridDim.x);

    if (global_tid < (long long)C) {
        const int c = (int)global_tid;
        const float count = (float)((long long)N * S);
        const float inv_count = 1.0f / count;

        if (training) {
            const float mean = g_sum[c] * inv_count;
            float var = g_sumsq[c] * inv_count - mean * mean;
            var = fmaxf(var, 0.0f);

            const float mom = (float)momentum;
            const float unbiased_var = (count > 1.0f) ? (var * count / (count - 1.0f)) : var;
            running_mean[c] = (1.0f - mom) * running_mean[c] + mom * mean;
            running_var[c] = (1.0f - mom) * running_var[c] + mom * unbiased_var;

            g_norm_mean[c] = mean;
            g_norm_inv[c] = rsqrtf(var + (float)eps);
        } else {
            g_norm_mean[c] = running_mean[c];
            g_norm_inv[c] = rsqrtf(running_var[c] + (float)eps);
        }
    }

    if (training && blockIdx.x == 0 && tid == 0) {
        *num_batches_tracked += 1;
    }
    grid_barrier(bar_counter, bar_gen, (unsigned int)gridDim.x);

    for (long long slice = blockIdx.x; slice < total_slices; slice += gridDim.x) {
        const int c = (int)(slice % (long long)C);
        const long long base = slice * S;
        const float mean = g_norm_mean[c];
        const float inv_std = g_norm_inv[c];
        const float gamma = weight[c];
        const float beta = bias[c];

        if ((S & 3LL) == 0LL) {
            const long long S4 = S >> 2;
            const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x + base);
            float4* __restrict__ y4 = reinterpret_cast<float4*>(y + base);
            const long long stride = (long long)blockDim.x;
            const long long unroll = stride << 2;
            long long s4 = tid;
            for (; s4 + 3 * stride < S4; s4 += unroll) {
                const float4 v0 = x4[s4];
                const float4 v1 = x4[s4 + stride];
                const float4 v2 = x4[s4 + 2 * stride];
                const float4 v3 = x4[s4 + 3 * stride];
                float4 r0;
                float4 r1;
                float4 r2;
                float4 r3;
                r0.x = (v0.x - mean) * inv_std * gamma + beta;
                r0.y = (v0.y - mean) * inv_std * gamma + beta;
                r0.z = (v0.z - mean) * inv_std * gamma + beta;
                r0.w = (v0.w - mean) * inv_std * gamma + beta;
                r1.x = (v1.x - mean) * inv_std * gamma + beta;
                r1.y = (v1.y - mean) * inv_std * gamma + beta;
                r1.z = (v1.z - mean) * inv_std * gamma + beta;
                r1.w = (v1.w - mean) * inv_std * gamma + beta;
                r2.x = (v2.x - mean) * inv_std * gamma + beta;
                r2.y = (v2.y - mean) * inv_std * gamma + beta;
                r2.z = (v2.z - mean) * inv_std * gamma + beta;
                r2.w = (v2.w - mean) * inv_std * gamma + beta;
                r3.x = (v3.x - mean) * inv_std * gamma + beta;
                r3.y = (v3.y - mean) * inv_std * gamma + beta;
                r3.z = (v3.z - mean) * inv_std * gamma + beta;
                r3.w = (v3.w - mean) * inv_std * gamma + beta;
                y4[s4] = r0;
                y4[s4 + stride] = r1;
                y4[s4 + 2 * stride] = r2;
                y4[s4 + 3 * stride] = r3;
            }
            for (; s4 < S4; s4 += stride) {
                const float4 v = x4[s4];
                float4 r;
                r.x = (v.x - mean) * inv_std * gamma + beta;
                r.y = (v.y - mean) * inv_std * gamma + beta;
                r.z = (v.z - mean) * inv_std * gamma + beta;
                r.w = (v.w - mean) * inv_std * gamma + beta;
                y4[s4] = r;
            }
        } else {
            for (long long s = tid; s < S; s += blockDim.x) {
                const long long idx = base + s;
                y[idx] = (x[idx] - mean) * inv_std * gamma + beta;
            }
        }
    }
}

torch::Tensor batchnorm_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor num_batches_tracked,
    double momentum,
    double eps,
    bool training)
{
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "only float32 is supported");
    TORCH_CHECK(x.dim() == 4, "expected NCHW input");
    TORCH_CHECK(x.is_contiguous(), "expected contiguous NCHW input");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "parameters must be CUDA");
    TORCH_CHECK(running_mean.is_cuda() && running_var.is_cuda(), "running stats must be CUDA");

    const int64_t N64 = x.size(0);
    const int64_t C64 = x.size(1);
    const int64_t H64 = x.size(2);
    const int64_t W64 = x.size(3);
    TORCH_CHECK(N64 > 0 && C64 > 0 && H64 > 0 && W64 > 0, "invalid input shape");
    TORCH_CHECK(C64 <= 2147483647LL, "too many channels");

    const int N = (int)N64;
    const int C = (int)C64;
    const long long S = (long long)(H64 * W64);

    auto y = at::empty_like(x);
    auto opts = x.options();
    auto g_sum = at::empty({C64}, opts);
    auto g_sumsq = at::empty({C64}, opts);
    auto g_norm_mean = at::empty({C64}, opts);
    auto g_norm_inv = at::empty({C64}, opts);
    auto bar = at::zeros({2}, opts.dtype(at::kInt));

    int device = 0;
    cudaGetDevice(&device);

    int supports_coop = 0;
    cudaDeviceGetAttribute(&supports_coop, cudaDevAttrCooperativeLaunch, device);
    TORCH_CHECK(supports_coop, "cooperative launch is not supported on this device");

    cudaDeviceProp prop;
    cudaGetDeviceProperties(&prop, device);

    int blocks_per_sm = 0;
    cudaError_t occ_err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &blocks_per_sm, bn2d_fused_kernel, BN_THREADS, 0);
    TORCH_CHECK(occ_err == cudaSuccess, cudaGetErrorString(occ_err));
    TORCH_CHECK(blocks_per_sm > 0, "invalid occupancy for fused batchnorm kernel");

    long long max_blocks = (long long)blocks_per_sm * (long long)prop.multiProcessorCount;
    long long wanted = (long long)N * (long long)C;
    int num_blocks = (int)std::min<long long>(max_blocks, std::max<long long>(wanted, 1LL));
    TORCH_CHECK(num_blocks > 0, "invalid grid size");

    const float* x_ptr = x.data_ptr<float>();
    float* y_ptr = y.data_ptr<float>();
    const float* w_ptr = weight.data_ptr<float>();
    const float* b_ptr = bias.data_ptr<float>();
    float* rm_ptr = running_mean.data_ptr<float>();
    float* rv_ptr = running_var.data_ptr<float>();
    int64_t* nbt_ptr = num_batches_tracked.data_ptr<int64_t>();
    float* gs_ptr = g_sum.data_ptr<float>();
    float* gsq_ptr = g_sumsq.data_ptr<float>();
    float* nm_ptr = g_norm_mean.data_ptr<float>();
    float* ni_ptr = g_norm_inv.data_ptr<float>();
    unsigned int* bar_cnt_ptr = reinterpret_cast<unsigned int*>(bar.data_ptr<int>());
    unsigned int* bar_gen_ptr = bar_cnt_ptr + 1;

    double mom = momentum;
    double ep = eps;
    bool train = training;
    int n_arg = N;
    int c_arg = C;
    long long s_arg = S;

    void* args[] = {
        (void*)&x_ptr,
        (void*)&y_ptr,
        (void*)&w_ptr,
        (void*)&b_ptr,
        (void*)&rm_ptr,
        (void*)&rv_ptr,
        (void*)&nbt_ptr,
        (void*)&gs_ptr,
        (void*)&gsq_ptr,
        (void*)&nm_ptr,
        (void*)&ni_ptr,
        (void*)&bar_cnt_ptr,
        (void*)&bar_gen_ptr,
        (void*)&n_arg,
        (void*)&c_arg,
        (void*)&s_arg,
        (void*)&mom,
        (void*)&ep,
        (void*)&train
    };

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    cudaError_t launch_err = cudaLaunchCooperativeKernel(
        (void*)bn2d_fused_kernel,
        dim3(num_blocks),
        dim3(BN_THREADS),
        args,
        0,
        stream);
    TORCH_CHECK(launch_err == cudaSuccess, cudaGetErrorString(launch_err));

    return y;
}
"""

_cpp_src = r"""
torch::Tensor batchnorm_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor num_batches_tracked,
    double momentum,
    double eps,
    bool training);
"""

_ext = load_inline(
    name="bn2d_fused_coop_v1",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["batchnorm_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class _BNState(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        self.register_parameter("weight", nn.Parameter(torch.ones(num_features)))
        self.register_parameter("bias", nn.Parameter(torch.zeros(num_features)))
        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.zeros((), dtype=torch.long))


class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        self.bn = _BNState(num_features)
        self.eps = 1e-5
        self.momentum = 0.1

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _ext.batchnorm_cuda(
            x,
            self.bn.weight,
            self.bn.bias,
            self.bn.running_mean,
            self.bn.running_var,
            self.bn.num_batches_tracked,
            float(self.momentum),
            float(self.eps),
            self.training,
        )

