            const long long S4 = S >> 2;
            const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x + base);
            float sum0 = 0.0f, sum1 = 0.0f, sum2 = 0.0f, sum3 = 0.0f;
            float sq0 = 0.0f, sq1 = 0.0f, sq2 = 0.0f, sq3 = 0.0f;
            const long long stride = (long long)blockDim.x;
            const long long unroll = stride << 2;
            long long s4 = tid;
            for (; s4 + 3 * stride < S4; s4 += unroll) {
                const float4 v0 = x4[s4];
                const float4 v1 = x4[s4 + stride];
                const float4 v2 = x4[s4 + 2 * stride];
                const float4 v3 = x4[s4 + 3 * stride];
                sum0 += (v0.x + v0.y) + (v0.z + v0.w);
                sum1 += (v1.x + v1.y) + (v1.z + v1.w);
                sum2 += (v2.x + v2.y) + (v2.z + v2.w);
                sum3 += (v3.x + v3.y) + (v3.z + v3.w);
                sq0 += (v0.x * v0.x + v0.y * v0.y) + (v0.z * v0.z + v0.w * v0.w);
                sq1 += (v1.x * v1.x + v1.y * v1.y) + (v1.z * v1.z + v1.w * v1.w);
                sq2 += (v2.x * v2.x + v2.y * v2.y) + (v2.z * v2.z + v2.w * v2.w);
                sq3 += (v3.x * v3.x + v3.y * v3.y) + (v3.z * v3.z + v3.w * v3.w);
