            const float mean = g_sum[c] * inv_count;
            float var = g_sumsq[c] * inv_count - mean * mean;
            var = fmaxf(var, 0.0f);

            const float mom = (float)momentum;
            const float unbiased_var = (count > 1.0f) ? (var * count / (count - 1.0f)) : var;
            running_mean[c] = (1.0f - mom) * running_mean[c] + mom * mean;
            running_var[c] = (1.0f - mom) * running_var[c] + mom * unbiased_var;

            g_norm_mean[c] = mean;
            g_norm_inv[c] = rsqrtf(var + (float)eps);
        } else {
            g_norm_mean[c] = running_mean[c];
            g_norm_inv[c] = rsqrtf(running_var[c] + (float)eps);
        }
    }

    if (training && blockIdx.x == 0 && tid == 0) {
        *num_batches_tracked += 1;
    }
    grid_barrier(bar_counter, bar_gen, (unsigned int)gridDim.x);

    for (long long slice = blockIdx.x; slice < total_slices; slice += gridDim.x) {
        const int c = (int)(slice % (long long)C);
        const long long base = slice * S;
        const float mean = g_norm_mean[c];
        const float inv_std = g_norm_inv[c];
        const float gamma = weight[c];
        const float beta = bias[c];

        if ((S & 3LL) == 0LL) {
            const long long S4 = S >> 2;
            const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x + base);
            float4* __restrict__ y4 = reinterpret_cast<float4*>(y + base);
            for (long long s4 = tid; s4 < S4; s4 += blockDim.x) {
                const float4 v = x4[s4];
                float4 r;
                r.x = (v.x - mean) * inv_std * gamma + beta;
                r.y = (v.y - mean) * inv_std * gamma + beta;
                r.z = (v.z - mean) * inv_std * gamma + beta;
                r.w = (v.w - mean) * inv_std * gamma + beta;
                y4[s4] = r;
            }
        } else {
            for (long long s = tid; s < S; s += blockDim.x) {
                const long long idx = base + s;
                y[idx] = (x[idx] - mean) * inv_std * gamma + beta;
            }
        }
    }
}

torch::Tensor batchnorm_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor num_batches_tracked,
    double momentum,
    double eps,
    bool training)
{
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "only float32 is supported");
    TORCH_CHECK(x.dim() == 4, "expected NCHW input");
    TORCH_CHECK(x.is_contiguous(), "expected contiguous NCHW input");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "parameters must be CUDA");
    TORCH_CHECK(running_mean.is_cuda() && running_var.is_cuda(), "running stats must be CUDA");

    const int64_t N64 = x.size(0);
    const int64_t C64 = x.size(1);
    const int64_t H64 = x.size(2);
    const int64_t W64 = x.size(3);
    TORCH_CHECK(N64 > 0 && C64 > 0 && H64 > 0 && W64 > 0, "invalid input shape");
    TORCH_CHECK(C64 <= 2147483647LL, "too many channels");

    const int N = (int)N64;
    const int C = (int)C64;
    const long long S = (long long)(H64 * W64);

    auto y = at::empty_like(x);
    auto opts = x.options();
    auto g_sum = at::empty({C64}, opts);
    auto g_sumsq = at::empty({C64}, opts);
    auto g_norm_mean = at::empty({C64}, opts);
    auto g_norm_inv = at::empty({C64}, opts);
    auto bar = at::zeros({2}, opts.dtype(at::kInt));

    int device = 0;
    cudaGetDevice(&device);

    int supports_coop = 0;
    cudaDeviceGetAttribute(&supports_coop, cudaDevAttrCooperativeLaunch, device);
    TORCH_CHECK(supports_coop, "cooperative launch is not supported on this device");

    cudaDeviceProp prop;
    cudaGetDeviceProperties(&prop, device);

    int blocks_per_sm = 0;
    cudaError_t occ_err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &blocks_per_sm, bn2d_fused_kernel, BN_THREADS, 0);
    TORCH_CHECK(occ_err == cudaSuccess, cudaGetErrorString(occ_err));
    TORCH_CHECK(blocks_per_sm > 0, "invalid occupancy for fused batchnorm kernel");

    long long max_blocks = (long long)blocks_per_sm * (long long)prop.multiProcessorCount;
    long long wanted = (long long)N * (long long)C;
    int num_blocks = (int)std::min<long long>(max_blocks, std::max<long long>(wanted, 1LL));
    TORCH_CHECK(num_blocks > 0, "invalid grid size");

    const float* x_ptr = x.data_ptr<float>();
    float* y_ptr = y.data_ptr<float>();
    const float* w_ptr = weight.data_ptr<float>();
    const float* b_ptr = bias.data_ptr<float>();
    float* rm_ptr = running_mean.data_ptr<float>();
    float* rv_ptr = running_var.data_ptr<float>();
    int64_t* nbt_ptr = num_batches_tracked.data_ptr<int64_t>();
    float* gs_ptr = g_sum.data_ptr<float>();
    float* gsq_ptr = g_sumsq.data_ptr<float>();
    float* nm_ptr = g_norm_mean.data_ptr<float>();
    float* ni_ptr = g_norm_inv.data_ptr<float>();
    unsigned int* bar_cnt_ptr = reinterpret_cast<unsigned int*>(bar.data_ptr<int>());
    unsigned int* bar_gen_ptr = bar_cnt_ptr + 1;

    double mom = momentum;
    double ep = eps;
    bool train = training;
    int n_arg = N;
    int c_arg = C;
    long long s_arg = S;

    void* args[] = {
        (void*)&x_ptr,
        (void*)&y_ptr,
        (void*)&w_ptr,
        (void*)&b_ptr,
        (void*)&rm_ptr,
        (void*)&rv_ptr,
        (void*)&nbt_ptr,
        (void*)&gs_ptr,
        (void*)&gsq_ptr,
        (void*)&nm_ptr,
        (void*)&ni_ptr,
        (void*)&bar_cnt_ptr,
        (void*)&bar_gen_ptr,
        (void*)&n_arg,
        (void*)&c_arg,
        (void*)&s_arg,
        (void*)&mom,
        (void*)&ep,
        (void*)&train
    };

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    cudaError_t launch_err = cudaLaunchCooperativeKernel(
        (void*)bn2d_fused_kernel,
        dim3(num_blocks),
        dim3(BN_THREADS),
        args,
        0,
        stream);
    TORCH_CHECK(launch_err == cudaSuccess, cudaGetErrorString(launch_err));

    return y;
}
